/* The waveform is drawn on a canvas, so its colours cannot come from CSS the way
   every other surface's do - they have to be handed to the 2d context. So they are
   read out of the custom properties in style.css once, and again only when the
   colour scheme changes. NEVER per draw: a getComputedStyle in the draw path is a
   forced style recalculation, and verify/index.html's render budget records what
   one of those costs per frame.

   Every token has a light-mode fallback, which is what keeps the headless harnesses
   working - a stub DOM's getComputedStyle has no getPropertyValue, and the draw
   list then comes out deterministic rather than empty. */
const THEME = {
  grid: '#d1d9e0', gridFaint: '#f6f8fa', label: '#59636e', text: '#1f2328',
  danger: '#cf222e', accent: '#0969da',
};
const PALETTE = [];   // filled by readTheme, so the traces follow the mode too

function readTheme() {
  let cs = null;
  try { cs = getComputedStyle(document.documentElement); } catch (e) { cs = null; }
  const tok = (name, fallback) => {
    try {
      const v = cs && typeof cs.getPropertyValue === 'function' ? cs.getPropertyValue(name) : '';
      return (v || '').trim() || fallback;
    } catch (e) { return fallback; }
  };
  THEME.grid = tok('--border-default', '#d1d9e0');
  THEME.gridFaint = tok('--canvas-subtle', '#f6f8fa');
  THEME.label = tok('--fg-muted', '#59636e');
  THEME.text = tok('--fg-default', '#1f2328');
  THEME.danger = tok('--danger-fg', '#cf222e');
  THEME.accent = tok('--accent-fg', '#0969da');
  // One token holding the whole trace palette, rather than eight tokens: the list
  // lives in style.css with everything else, and its length is the palette's.
  const list = tok('--wave-palette', '#0969da,#1a7f37,#9a6700,#cf222e,#8250df,#1b7c83,#bc4c00,#6e7781')
    .split(',').map(s => s.trim()).filter(Boolean);
  PALETTE.length = 0;
  for (const c of list) PALETTE.push(c);
}
readTheme();

// Following the OS is the whole point of reading the tokens, so a change has to
// re-read and redraw - the canvas keeps whatever colours it was painted with.
if (typeof window.matchMedia === 'function') {
  const mq = window.matchMedia('(prefers-color-scheme: dark)');
  const onScheme = () => { readTheme(); if (lastResult) drawWaveform(lastResult); };
  if (mq && typeof mq.addEventListener === 'function') mq.addEventListener('change', onScheme);
}
