let lastTopModuleName = null; // top module's modType from the last run - a change means a new design, so visibility resets to top-only-visible
let expandedHierarchyPaths = new Set(); // module-instance paths whose own-signal checklist is open
let collapsedBranches = new Set(); // module-instance paths whose child sub-instance rows are folded out of the tree view (the +/- box) - purely a display fold, independent of waveform visibility
let declKindMap = new Map();   // fullName -> {kind, ioKind}, from the last successful parse's decls
let clockSignalNames = new Set(); // fullNames used with posedge/negedge anywhere - drawn with the clock icon
let hierarchyDragState = null; // { listEl, paintVisible } while a signal-list drag-to-toggle is in progress
window.addEventListener('mouseup', () => { hierarchyDragState = null; });
let radixMap = new Map();      // signal name -> 'bin' | 'dec' | 'sdec' | 'hex' | 'str'
let cursorTime = 0;            // scrub position; drives the value column
let viewStart = 0, viewEnd = 1; // current zoom/pan window over sim time
let hoverValueSignal = null;   // signal whose value cell is currently hovered
let hoverNameSignal = null;    // signal whose (canvas-drawn) name label is currently hovered
let hoverNameDivider = false;  // pointer is within the name/value divider's drag hit-zone
let resizingNameCol = false;   // divider drag in progress
let resizeStartMx = 0;         // mousedown x when the resize drag started, in canvas CSS px
let resizeStartWidth = 0;      // NAME_W at the moment the resize drag started
let waveLayout = null;         // layout info from the last draw, used by mouse handlers
let dragActive = false;        // mouse button down, originating inside the plot area
let dragMoved = false;         // drag exceeded the click-vs-drag pixel threshold
let dragStartX = 0;            // mousedown x, in canvas CSS px
let dragBandPx = null;         // {x0,x1} selection band while dragging, or null

/* ---- radix formatting for the waveform value column ---- */
const RADIX_OPTIONS = [['bin', 'Binary'], ['dec', 'Decimal'], ['sdec', 'Signed Decimal'], ['hex', 'Hexadecimal'], ['str', 'String']];
// A signal whose DECLARED name begins with this is taken to carry ASCII, so it
// defaults to the String radix instead of hex. Matched on the leaf name (the text
// after the last dot) rather than the flattened path, so it works at any hierarchy
// depth - elaboration turns it into u_sys.u_cpu.debug_msg - and so an instance
// named u_debug_* cannot drag every signal inside it into String too.
const DEBUG_STR_PREFIX = 'debug_';
function getRadix(name, width) {
  const explicit = radixMap.get(name);
  if (explicit) return explicit;
  // 1-bit signals are excluded: String renders 0 as '-' and 1 as '.' (non-printable),
  // which is strictly less readable than the binary it replaces.
  if (width > 1 && name.slice(name.lastIndexOf('.') + 1).startsWith(DEBUG_STR_PREFIX)) return 'str';
  return width === 1 ? 'bin' : 'hex';
}
function bitState1(val) {
  if (val.x & 1) return 'x';
  if (val.z & 1) return 'z';
  return (val.v & 1) ? '1' : '0';
}
function toSigned(uv, width) {
  if (width >= 32) return uv | 0;
  const signBit = 1 << (width - 1);
  return (uv & signBit) ? uv - (1 << width) : uv;
}
function formatValue(value, width, radix) {
  const effWidth = Math.min(width, 32);
  if (!isFullyKnown(value)) {
    switch (radix) {
      case 'bin': return formatDigitGroups(value, 1, effWidth, true);
      case 'dec': case 'sdec': return isFullyKnown(value) ? String(value.v >>> 0) : 'X';
      case 'str': {
        const byteCount = Math.ceil(effWidth / 8);
        let s = '';
        for (let i = byteCount - 1; i >= 0; i--) {
          const shift = i * 8;
          const vB = (value.v >>> shift) & 0xFF, xB = (value.x >>> shift) & 0xFF, zB = (value.z >>> shift) & 0xFF;
          if (vB === 0 && xB === 0 && zB === 0) continue;
          s += (xB || zB) ? '?' : ((vB >= 0x20 && vB <= 0x7e) ? String.fromCharCode(vB) : '.');
        }
        return s || '–';
      }
      default: return formatDigitGroups(value, 4, Math.ceil(effWidth / 4), true);
    }
  }
  const uv = value.v >>> 0;
  switch (radix) {
    case 'bin': return uv.toString(2).padStart(effWidth, '0');
    case 'dec': return String(uv);
    case 'sdec': return String(toSigned(uv, effWidth));
    case 'str': {
      const byteCount = Math.ceil(effWidth / 8);
      let s = '';
      for (let i = byteCount - 1; i >= 0; i--) {
        const b = (uv >>> (i * 8)) & 0xFF;
        if (b === 0) continue;
        s += (b >= 0x20 && b <= 0x7e) ? String.fromCharCode(b) : '.';
      }
      return s || '–';
    }
    default: return uv.toString(16).padStart(Math.ceil(effWidth / 4), '0');
  }
}
function valueAtTime(sig, t) {
  const hist = sig.history;
  let v = hist[0][1];
  for (let i = 0; i < hist.length && hist[i][0] <= t; i++) v = hist[i][1];
  return v;
}

/* ---- radix picker popup ---- */
const radixPopup = document.createElement('div');
radixPopup.className = 'radix-popup';
document.body.appendChild(radixPopup);
let radixHideTimer = null;
function showRadixPopup(name, width, x, y) {
  clearTimeout(radixHideTimer);
  const radix = getRadix(name, width);
  radixPopup.innerHTML = '<div class="radix-popup-title">Radix</div>' +
    RADIX_OPTIONS.map(([key, label]) =>
      '<div class="radix-opt' + (key === radix ? ' selected' : '') + '" data-radix="' + key + '">' + label + '</div>'
    ).join('');
  radixPopup.style.left = x + 'px';
  radixPopup.style.top = y + 'px';
  radixPopup.style.display = 'block';
  radixPopup.querySelectorAll('.radix-opt').forEach(el => {
    el.addEventListener('click', () => {
      radixMap.set(name, el.dataset.radix);
      hideRadixPopup();
      if (lastResult) drawWaveform(lastResult);
    });
  });
}
function hideRadixPopup() {
  radixPopup.style.display = 'none';
  hoverValueSignal = null;
}
function scheduleHideRadixPopup() {
  clearTimeout(radixHideTimer);
  radixHideTimer = setTimeout(hideRadixPopup, 200);
}
radixPopup.addEventListener('mouseenter', () => clearTimeout(radixHideTimer));
radixPopup.addEventListener('mouseleave', scheduleHideRadixPopup);

/* ---- signal name tooltip (row labels are drawn in a fixed-width canvas
   column, so a long hierarchical name like u0.sub.bit1.clk can run past it
   with no wrap/ellipsis - this surfaces the untruncated name on hover) ---- */
const nameTooltip = document.createElement('div');
nameTooltip.className = 'wave-tooltip';
document.body.appendChild(nameTooltip);
function showNameTooltip(name, x, y) {
  nameTooltip.textContent = name;
  nameTooltip.style.left = x + 'px';
  nameTooltip.style.top = y + 'px';
  nameTooltip.style.display = 'block';
}
function hideNameTooltip() { nameTooltip.style.display = 'none'; }

/* ---- waveform zoom / pan controls ---- */
const WAVE_ZOOM_FACTOR = 1.6;
function waveFullRange() { return [0, lastResult ? Math.max(lastResult.time, 1) : 1]; }
function waveZoomAt(centerTime) {
  if (!lastResult) return;
  const [fullMin, fullMax] = waveFullRange();
  const half = (viewEnd - viewStart) / (2 * WAVE_ZOOM_FACTOR);
  viewStart = Math.max(fullMin, centerTime - half);
  viewEnd = Math.min(fullMax, centerTime + half);
  if (viewEnd - viewStart < 1) { viewStart = centerTime - 0.5; viewEnd = centerTime + 0.5; }
  drawWaveform(lastResult);
}
function waveZoomIn() { if (lastResult) waveZoomAt((viewStart + viewEnd) / 2); }
function waveZoomOut() {
  if (!lastResult) return;
  const [fullMin, fullMax] = waveFullRange();
  const center = (viewStart + viewEnd) / 2;
  const half = (viewEnd - viewStart) * WAVE_ZOOM_FACTOR / 2;
  viewStart = Math.max(fullMin, center - half);
  viewEnd = Math.min(fullMax, center + half);
  drawWaveform(lastResult);
}
function waveZoomReset() {
  if (!lastResult) return;
  [viewStart, viewEnd] = waveFullRange();
  drawWaveform(lastResult);
}
// Pans the view by a fraction of its own current width, preserving the
// current zoom level (window width) rather than changing it - clamped so
// scrolling stops at the data's actual boundaries instead of drifting into
// empty space beyond t=0 or the end of the simulation.
function waveScrollBy(fraction) {
  if (!lastResult) return;
  const [fullMin, fullMax] = waveFullRange();
  const width = viewEnd - viewStart;
  let newStart = viewStart + width * fraction;
  let newEnd = viewEnd + width * fraction;
  if (newStart < fullMin) { newStart = fullMin; newEnd = fullMin + width; }
  if (newEnd > fullMax) { newEnd = fullMax; newStart = fullMax - width; }
  viewStart = newStart; viewEnd = newEnd;
  drawWaveform(lastResult);
}
function waveScrollLeft() { waveScrollBy(-0.5); }
function waveScrollRight() { waveScrollBy(0.5); }
// Sets the view to `span` time units wide with `anchorTime` sitting at fractional
// position `anchorFrac` across the plot - i.e. zooms about a fixed point, which is
// what makes the touch zoom drag feel anchored under the finger. A window that
// lands outside the data is SHIFTED back inside rather than shrunk (same shape as
// waveScrollBy's clamping), so zooming near t=0 or the end doesn't silently
// change the span the caller asked for.
const WAVE_MIN_SPAN = 1; // same floor waveZoomAt uses
function waveSetSpanAround(anchorTime, anchorFrac, span) {
  if (!lastResult) return;
  const [fullMin, fullMax] = waveFullRange();
  span = Math.max(WAVE_MIN_SPAN, Math.min(fullMax - fullMin, span));
  let start = anchorTime - anchorFrac * span;
  let end = start + span;
  if (start < fullMin) { start = fullMin; end = fullMin + span; }
  if (end > fullMax) { end = fullMax; start = fullMax - span; }
  viewStart = start; viewEnd = end;
  drawWaveform(lastResult);
}
function waveApplyRange() {
  if (!lastResult) return;
  const s = parseFloat(waveStartInput.value);
  const e = parseFloat(waveEndInput.value);
  waveStartInput.classList.remove('error');
  waveEndInput.classList.remove('error');
  let ok = true;
  if (isNaN(s)) { waveStartInput.classList.add('error'); ok = false; }
  if (isNaN(e)) { waveEndInput.classList.add('error'); ok = false; }
  if (ok && e <= s) { waveStartInput.classList.add('error'); waveEndInput.classList.add('error'); ok = false; }
  if (!ok) return;
  viewStart = s; viewEnd = e;
  drawWaveform(lastResult);
}
waveZoomInBtn.addEventListener('click', waveZoomIn);
waveZoomOutBtn.addEventListener('click', waveZoomOut);
waveZoomResetBtn.addEventListener('click', waveZoomReset);
waveScrollLeftBtn.addEventListener('click', waveScrollLeft);
waveScrollRightBtn.addEventListener('click', waveScrollRight);
waveApplyBtn.addEventListener('click', waveApplyRange);
waveStartInput.addEventListener('keydown', e => { if (e.key === 'Enter') waveApplyRange(); });
waveEndInput.addEventListener('keydown', e => { if (e.key === 'Enter') waveApplyRange(); });

